}

export async function reinstateMember(actor: Actor, input: { orgId: OrgId; memberId: MemberId }): Promise<Member> {
  assertOrgScope(actor, input.orgId);
  const member = requireFound(await memberRepo.findMemberById(input.orgId, input.memberId), "Member", input.memberId);
  if (member.archivedAt !== null) throw new NotFoundError("Member", input.memberId);
  assertCan(actor, "member:remove", memberResource(member));
  if (member.userId === actor.userId || !hasRoleAtLeast(actor.role, member.role)) throw new Error("Cannot reinstate this member");
  if (member.status !== "suspended") return member;
  const updated = await memberRepo.setMemberStatus(input.orgId, input.memberId, "active");
  await emit("member.reinstated", { ...actorEnvelope(actor), memberId: updated.id, userId: updated.userId });
  return updated;
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

